    struct sockaddr_nl sa = {.nl_family = AF_NETLINK, .nl_pid = getpid()};
    if (bind(nl_sock, (void*)&sa, sizeof(sa)) < 0) { perror("bind"); return 1;}
    nl_family_id = resolve_genl_family(nl_sock, KSMBD_GENL_NAME);
