+);
+DEFINE_EVENT(dpu_func_template, spacemit_crtc_atomic_flush,
+	     TP_PROTO(u32 dev_id),
+	TP_ARGS(dev_id)
+);
+DEFINE_EVENT(dpu_func_template, spacemit_crtc_enable_vblank,
+	     TP_PROTO(u32 dev_id),
+	TP_ARGS(dev_id)
+);
+DEFINE_EVENT(dpu_func_template, spacemit_crtc_disable_vblank,
+	     TP_PROTO(u32 dev_id),
