+	),
+	TP_printk("%s", __get_str(dump_str))
+);
+
+TRACE_EVENT(cmdlist_dump_node,
+	    TP_PROTO(char *type, int rdma_id, u8 dev_id, int zpos, u16 nod_len),
+	TP_ARGS(type, rdma_id, dev_id, zpos, nod_len),
+	TP_STRUCT__entry(
+		__string(type_str, type)
+		__field(int, rdma_id)
